#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>

typedef struct { const uint8_t *s; size_t n,p,line,col; char *err; size_t errn; } JP;
static void jerr(JP*j,const char*msg){if(j->err&&j->errn)snprintf(j->err,j->errn,"%s",msg);}
static int adv(JP*j){if(j->p>=j->n)return -1;int c=j->s[j->p++];if(c=='\n'){j->line++;j->col=1;}else j->col++;return c;}
static void ws(JP*j){while(j->p<j->n&&(j->s[j->p]==' '||j->s[j->p]=='\t'||j->s[j->p]=='\r'||j->s[j->p]=='\n'))adv(j);}
static DarcValue *vnew(DarcValType t){DarcValue*v=darc_calloc(1,sizeof*v);if(v)v->t=t;return v;}
void darc_value_free(DarcValue*v){if(!v)return;switch(v->t){case V_STR:free(v->u.str.s);break;case V_ARR:for(size_t i=0;i<v->u.arr.n;i++)darc_value_free(v->u.arr.v[i]);free(v->u.arr.v);break;case V_OBJ:for(size_t i=0;i<v->u.obj.n;i++){free(v->u.obj.v[i].key);darc_value_free(v->u.obj.v[i].val);}free(v->u.obj.v);break;default:break;}free(v);}
static int arr_add(DarcValue*v,DarcValue*x){if(v->u.arr.n==v->u.arr.cap){size_t nc=v->u.arr.cap?v->u.arr.cap*2:8;DarcValue**p=darc_realloc(v->u.arr.v,nc*sizeof*p);if(!p)return -1;v->u.arr.v=p;v->u.arr.cap=nc;}v->u.arr.v[v->u.arr.n++]=x;return 0;}
static int obj_add(DarcValue*v,char*k,DarcValue*x){for(size_t i=0;i<v->u.obj.n;i++)if(!strcmp(v->u.obj.v[i].key,k))return 1;if(v->u.obj.n==v->u.obj.cap){size_t nc=v->u.obj.cap?v->u.obj.cap*2:8;DarcPair*p=darc_realloc(v->u.obj.v,nc*sizeof*p);if(!p)return -1;v->u.obj.v=p;v->u.obj.cap=nc;}v->u.obj.v[v->u.obj.n++]=(DarcPair){k,x};return 0;}
static int hex4(JP*j,uint32_t*out){uint32_t x=0;for(int i=0;i<4;i++){if(j->p>=j->n)return -1;int c=adv(j),v;if(c>='0'&&c<='9')v=c-'0';else if(c>='a'&&c<='f')v=c-'a'+10;else if(c>='A'&&c<='F')v=c-'A'+10;else return -1;x=(x<<4)|(uint32_t)v;}*out=x;return 0;}
static int put_utf8(DarcBuf*b,uint32_t cp){uint8_t p[4];size_t n;if(cp<=0x7f){p[0]=(uint8_t)cp;n=1;}else if(cp<=0x7ff){p[0]=(uint8_t)(0xc0|(cp>>6));p[1]=(uint8_t)(0x80|(cp&63));n=2;}else if(cp<=0xffff){p[0]=(uint8_t)(0xe0|(cp>>12));p[1]=(uint8_t)(0x80|((cp>>6)&63));p[2]=(uint8_t)(0x80|(cp&63));n=3;}else if(cp<=0x10ffff){p[0]=(uint8_t)(0xf0|(cp>>18));p[1]=(uint8_t)(0x80|((cp>>12)&63));p[2]=(uint8_t)(0x80|((cp>>6)&63));p[3]=(uint8_t)(0x80|(cp&63));n=4;}else return -1;return darc_buf_put(b,p,n);}
static char *parse_str(JP*j){if(adv(j)!='"')return NULL;DarcBuf b;darc_buf_init(&b);while(j->p<j->n){int c=adv(j);if(c=='"'){if(!darc_valid_utf8(b.data,b.len)){jerr(j,"invalid UTF-8 in string");darc_buf_free(&b);return NULL;}if(darc_buf_u8(&b,0)){darc_buf_free(&b);return NULL;}return (char*)b.data;}if(c<0x20){jerr(j,"control character in string");darc_buf_free(&b);return NULL;}if(c=='\\'){if(j->p>=j->n)goto bad;c=adv(j);switch(c){case '"':case '\\':case '/':if(darc_buf_u8(&b,(uint8_t)c))goto oom;break;case 'b':if(darc_buf_u8(&b,'\b'))goto oom;break;case 'f':if(darc_buf_u8(&b,'\f'))goto oom;break;case 'n':if(darc_buf_u8(&b,'\n'))goto oom;break;case 'r':if(darc_buf_u8(&b,'\r'))goto oom;break;case 't':if(darc_buf_u8(&b,'\t'))goto oom;break;case 'u':{uint32_t cp;if(hex4(j,&cp))goto bad;if(cp>=0xd800&&cp<=0xdbff){if(j->p+2>j->n||adv(j)!='\\'||adv(j)!='u')goto bad;uint32_t lo;if(hex4(j,&lo)||lo<0xdc00||lo>0xdfff)goto bad;cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)goto bad;if(put_utf8(&b,cp))goto oom;break;}default:goto bad;}}else if(darc_buf_u8(&b,(uint8_t)c))goto oom;}bad:jerr(j,"malformed or unterminated string");darc_buf_free(&b);return NULL;oom:jerr(j,"out of memory");darc_buf_free(&b);return NULL;}
static DarcValue *parse_val(JP*j,int depth);
static DarcValue *parse_arr(JP*j,int depth){adv(j);DarcValue*v=vnew(V_ARR);if(!v)return NULL;ws(j);if(j->p<j->n&&j->s[j->p]==']'){adv(j);return v;}for(;;){DarcValue*x=parse_val(j,depth+1);if(!x){darc_value_free(v);return NULL;}if(arr_add(v,x)){darc_value_free(x);darc_value_free(v);jerr(j,"out of memory");return NULL;}ws(j);if(j->p>=j->n){jerr(j,"unterminated array");darc_value_free(v);return NULL;}int c=adv(j);if(c==']')return v;if(c!=','){jerr(j,"expected comma or ]");darc_value_free(v);return NULL;}ws(j);if(j->p<j->n&&j->s[j->p]==']'){jerr(j,"trailing comma");darc_value_free(v);return NULL;}}
}
static DarcValue *parse_obj(JP*j,int depth){adv(j);DarcValue*v=vnew(V_OBJ);if(!v)return NULL;ws(j);if(j->p<j->n&&j->s[j->p]=='}'){adv(j);return v;}for(;;){if(j->p>=j->n||j->s[j->p]!='"'){jerr(j,"expected object key string");darc_value_free(v);return NULL;}char*k=parse_str(j);if(!k){darc_value_free(v);return NULL;}ws(j);if(j->p>=j->n||adv(j)!=':'){free(k);jerr(j,"expected colon");darc_value_free(v);return NULL;}ws(j);DarcValue*x=parse_val(j,depth+1);if(!x){free(k);darc_value_free(v);return NULL;}int a=obj_add(v,k,x);if(a){if(a==1)jerr(j,"duplicate object key");else jerr(j,"out of memory");free(k);darc_value_free(x);darc_value_free(v);return NULL;}ws(j);if(j->p>=j->n){jerr(j,"unterminated object");darc_value_free(v);return NULL;}int c=adv(j);if(c=='}')return v;if(c!=','){jerr(j,"expected comma or }");darc_value_free(v);return NULL;}ws(j);if(j->p<j->n&&j->s[j->p]=='}'){jerr(j,"trailing comma");darc_value_free(v);return NULL;}}
}
static DarcValue *parse_num(JP*j){size_t st=j->p;if(j->s[j->p]=='-')j->p++;if(j->p>=j->n)return NULL;if(j->s[j->p]=='0'){j->p++;if(j->p<j->n&&isdigit(j->s[j->p])){jerr(j,"leading zero in number");return NULL;}}else if(j->s[j->p]>='1'&&j->s[j->p]<='9'){while(j->p<j->n&&isdigit(j->s[j->p]))j->p++;}else return NULL;bool fl=false;if(j->p<j->n&&j->s[j->p]=='.'){fl=true;j->p++;if(j->p>=j->n||!isdigit(j->s[j->p]))return NULL;while(j->p<j->n&&isdigit(j->s[j->p]))j->p++;}if(j->p<j->n&&(j->s[j->p]=='e'||j->s[j->p]=='E')){fl=true;j->p++;if(j->p<j->n&&(j->s[j->p]=='+'||j->s[j->p]=='-'))j->p++;if(j->p>=j->n||!isdigit(j->s[j->p]))return NULL;while(j->p<j->n&&isdigit(j->s[j->p]))j->p++;}size_t ln=j->p-st;char*tmp=darc_strndup((const char*)j->s+st,ln);if(!tmp)return NULL;DarcValue*v=NULL;if(!fl){errno=0;char*e;long long x=strtoll(tmp,&e,10);if(errno==ERANGE||*e){jerr(j,"integer overflow");free(tmp);return NULL;}v=vnew(V_INT);if(v)v->u.i=(int64_t)x;}else{errno=0;char*e;double x=strtod(tmp,&e);if(errno==ERANGE||*e){jerr(j,"invalid number");free(tmp);return NULL;}v=vnew(V_NUM);if(v)v->u.num=x;}free(tmp);return v;}
static DarcValue *parse_val(JP*j,int depth){if(depth>DARC_MAX_CONFIG_DEPTH){jerr(j,"nesting depth exceeded");return NULL;}ws(j);if(j->p>=j->n){jerr(j,"unexpected EOF");return NULL;}uint8_t c=j->s[j->p];if(c=='{')return parse_obj(j,depth);if(c=='[')return parse_arr(j,depth);if(c=='"'){char*s=parse_str(j);if(!s)return NULL;DarcValue*v=vnew(V_STR);if(!v){free(s);return NULL;}v->u.str.s=s;v->u.str.len=strlen(s);return v;}if(c=='t'&&j->n-j->p>=4&&!memcmp(j->s+j->p,"true",4)){j->p+=4;DarcValue*v=vnew(V_BOOL);if(v)v->u.b=true;return v;}if(c=='f'&&j->n-j->p>=5&&!memcmp(j->s+j->p,"false",5)){j->p+=5;DarcValue*v=vnew(V_BOOL);if(v)v->u.b=false;return v;}if(c=='n'&&j->n-j->p>=4&&!memcmp(j->s+j->p,"null",4)){j->p+=4;return vnew(V_NULL);}if(c=='-'||isdigit(c)){DarcValue*v=parse_num(j);if(!v&&(!j->err||!*j->err))jerr(j,"invalid number");return v;}jerr(j,"unexpected token");return NULL;}
DarcValue *darc_json_parse(const uint8_t*s,size_t n,char*err,size_t errn,size_t*line,size_t*col){if(err&&errn)*err=0;if(!darc_valid_utf8(s,n)){if(err&&errn)snprintf(err,errn,"malformed UTF-8");if(line)*line=1;if(col)*col=1;return NULL;}JP j={s,n,0,1,1,err,errn};if(n>=3&&s[0]==0xef&&s[1]==0xbb&&s[2]==0xbf){j.p=3;j.col=4;}DarcValue*v=parse_val(&j,0);if(v){ws(&j);if(j.p!=j.n){jerr(&j,"trailing garbage");darc_value_free(v);v=NULL;}}if(line)*line=j.line;if(col)*col=j.col;return v;}
